const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');

// ---------------------------------------------------------------------------
// Conformance: Perturbation quiescence
// ---------------------------------------------------------------------------

Given('the project has a perturbation token in its implementation', function () {
  // Always true — the scenario checks for its absence after loading
  this.perturbationFiles = [];
  const implDirs = ['.', 'js'];
  const marker = /PERTURBATION/i;
  for (const dir of implDirs) {
    const absDir = path.resolve(ROOT, dir);
    if (!fs.existsSync(absDir)) continue;
    const entries = fs.readdirSync(absDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isFile() && entry.name.endsWith('.js')) {
        const content = fs.readFileSync(path.join(absDir, entry.name), 'utf8');
        if (marker.test(content)) {
          this.perturbationFiles.push(path.join(dir, entry.name));
        }
      }
    }
  }
  // No-op; the When step will perform the search
});

When('I search for the PERTURBATION marker in implementation files', function () {
  // this.perturbationFiles is already populated by the Given step
});

Then('the token is absent, or verification is red', function () {
  // If a PERTURBATION marker exists AND verification is green, that's a violation.
  // This scenario is tagged @conformance so it runs during conformance checks,
  // not during normal verification. We check the files here.
  if (this.perturbationFiles.length > 0) {
    assert.fail(
      `PERTURBATION token found in implementation files: ${this.perturbationFiles.join(', ')}\n` +
      'Remove the token before shipping.'
    );
  }
});

// ---------------------------------------------------------------------------
// Conformance: Watchbill shape
// ---------------------------------------------------------------------------

Given('the project has a watchbill at the repository root', function () {
  const watchbillPath = path.join(ROOT, 'watchbill.json');
  this.watchbillExists = fs.existsSync(watchbillPath);
  if (this.watchbillExists) {
    try {
      this.watchbill = JSON.parse(fs.readFileSync(watchbillPath, 'utf8'));
    } catch (e) {
      this.watchbill = null;
    }
  }
});

When('I validate its shape against the Watchbill policy', function () {
  // Shape validation: must be an array of objects with "scenario" string
  if (this.watchbillExists) {
    this.watchbillValid = Array.isArray(this.watchbill) &&
      this.watchbill.every(item =>
        item !== null &&
        typeof item === 'object' &&
        typeof item.scenario === 'string'
      );
  } else {
    this.watchbillValid = null; // absent = conforming by construction
  }
});

Then('the watchbill is valid, or absent and conforming', function () {
  if (this.watchbillExists) {
    assert.ok(this.watchbillValid,
      'watchbill.json exists but has an invalid shape. Expected an array of objects with "scenario" strings.');
  }
  // If absent, it's conforming by construction
});

// ---------------------------------------------------------------------------
// Conformance: DOM identity preservation
// ---------------------------------------------------------------------------

Given('the project has a render function that writes to the todo list', function () {
  const appPath = path.join(ROOT, 'js', 'app.js');
  assert.ok(fs.existsSync(appPath), 'js/app.js not found');
  const source = fs.readFileSync(appPath, 'utf8');
  this.appSource = source;
  // Check that a render-like function exists (contains "render" reference and todo-list usage)
  const hasRender = /render/i.test(source);
  const writesToList = /todoList/i.test(source) || /\.todo-list/i.test(source);
  assert.ok(hasRender && writesToList,
    'Expected a render function that writes to the todo list');
});

When('I check whether the render function assigns innerHTML on the todo-list container', function () {
  const source = this.appSource;
  // Look for patterns like: todoList.innerHTML =  or  .querySelector('.todo-list').innerHTML =
  const innerHtmlOnList = (
    /todoList\.innerHTML\s*=/.test(source) ||
    /\.todo-list['"]?\)?\.innerHTML\s*=/.test(source) ||
    /todo-list['"]?\s*\)?\s*\.innerHTML\s*=/.test(source)
  );
  this.usesInnerHtmlOnList = innerHtmlOnList;
});

Then('the render function does not use innerHTML reassignment on the todo list', function () {
  assert.ok(!this.usesInnerHtmlOnList,
    'FAIL: The render function assigns innerHTML on the todo list container. ' +
    'This destroys all existing <li> DOM nodes, detaching references held by the browser. ' +
    'FIX: Mutate existing nodes in place — toggle classes, update .checked, change textContent — ' +
    'instead of rebuilding the full list via innerHTML.');
});

Given('the project has a render function that handles completion state', function () {
  const appPath = path.join(ROOT, 'js', 'app.js');
  assert.ok(fs.existsSync(appPath), 'js/app.js not found');
  const source = fs.readFileSync(appPath, 'utf8');
  this.appSource = source;
  const handlesCompletion = /completed|toggle|completedClass|checked/.test(source);
  assert.ok(handlesCompletion,
    'Expected a render function that handles completion state');
});

When('I check whether a completion toggle triggers a full innerHTML rebuild', function () {
  const source = this.appSource;
  // Look for patterns indicating innerHTML rebuild in toggle-related code
  // The key pattern is: render() is called after toggle AND render rebuilds via innerHTML
  const hasToggleFunction = /function\s+toggle/i.test(source);
  const hasRenderCall = /render\s*\(/.test(source);
  const hasInnerHtmlRebuild = (
    /todoList\.innerHTML\s*=/.test(source) ||
    /innerHTML\s*=.*\+/.test(source) ||
    /innerHTML\s*=\s*['"]/.test(source)
  );
  this.toggleTriggersFullRebuild = hasToggleFunction && hasRenderCall && hasInnerHtmlRebuild;
});

Then('a completion toggle does not rebuild the list via innerHTML', function () {
  assert.ok(!this.toggleTriggersFullRebuild,
    'FAIL: A completion toggle triggers a full innerHTML rebuild of the todo list. ' +
    'This detaches all existing DOM nodes, causing Cypress "element detached from DOM" errors. ' +
    'FIX: When toggling completion, mutate the existing <li> node in place: ' +
    'add/remove the "completed" class on the parent <li>, toggle the checkbox .checked property, ' +
    'rather than calling render() which rebuilds the entire list.');
});

// ---------------------------------------------------------------------------
// Conformance: Unconditional removeChild anti-pattern
// ---------------------------------------------------------------------------

When('I check whether the render function removes all existing list-item children unconditionally', function () {
  const source = this.appSource;
  // Detect the anti-pattern where ALL existing <li> children are removed from the DOM
  // in a loop that has NO conditional guard (no if-statement before removeChild).
  //
  // The bug: for (var id in existingItems) {
  //           existingItems[id].parentNode.removeChild(existingItems[id]);
  //           delete existingItems[id];
  //         }
  //
  // This removes EVERY child node unconditionally, even ones that should be kept.
  //
  // Look for a loop body that calls removeChild without a preceding if.
  // We match:  for (...) {  ... removeChild( ...
  // where there is NO 'if' keyword between '{' and 'removeChild'.
  const unconditionaRemovePattern = /for\s*\([^{]*\)\s*\{[^{}]*removeChild\s*\(/s;
  this.hasUnconditionalRemoveAll = unconditionaRemovePattern.test(source);
});

Then('the render function does not remove existing list-item children unless they are stale', function () {
  assert.ok(!this.hasUnconditionalRemoveAll,
    'FAIL: The render function removes ALL existing <li> children unconditionally. ' +
    'This detaches every existing DOM node, causing Cypress "element detached from DOM" errors. ' +
    'The code iterates over all existing list items and calls removeChild on each ' +
    'without checking whether the item is still in the filtered todo list. ' +
    'FIX: Only remove child nodes whose data-id is NOT in the current filtered set; ' +
    'keep and mutate the rest in place (toggle class, update .checked, change textContent).');
});

// ---------------------------------------------------------------------------
// Conformance: Always-creates-new-li anti-pattern
// ---------------------------------------------------------------------------

When('I check whether the render function creates new list-item elements for items that already exist', function () {
  const source = this.appSource;
  // Detect the anti-pattern where the render function deletes ALL items from the
  // existing-items tracking map (using `delete existingItems[id]` in a loop) BEFORE
  // the reuse loop runs. This means the `existingItems[t.id]` lookup always returns
  // undefined, and createElement('li') is ALWAYS called — the reuse branch is dead code.
  //
  // The buggy pattern:
  //   for (var id in existingItems) {
  //     existingItems[id].parentNode.removeChild(existingItems[id]);
  //     delete existingItems[id];   // map emptied
  //   }
  //   for (var i = ...) {
  //     var li = existingItems[t.id]; // always undefined
  //     if (li) { ... reuse ... }     // dead code
  //     else { createElement('li') ... } // always runs
  //   }
  //
  // We detect: a loop that calls `delete` on existingItems entries, destroying the
  // tracking map, combined with createElement('li') later on.
  const hasDeleteFromMap = /delete\s+existingItems\[/.test(source);
  const hasCreateLi = /createElement\s*\(\s*['"]li['"]\s*\)/.test(source);
  // Fail if the map is cleared by delete AND new li elements are created
  // (meaning the reuse lookup can never succeed).
  this.alwaysCreatesNewLis = hasDeleteFromMap && hasCreateLi;
});

Then('the render function reuses existing list-item elements for items that are already in the DOM', function () {
  assert.ok(!this.alwaysCreatesNewLis,
    'FAIL: The render function deletes all items from the existing-items tracking map ' +
    'before the reuse loop, so existingItems[t.id] always returns undefined. ' +
    'createElement("li") is always called — the reuse/update branch is dead code. ' +
    'FIX: In the stale-removal loop, only `delete` items that are NOT in the filtered ' +
    'todo set. Keep items that should be preserved in the map so they can be reused ' +
    'and mutated in place instead of being recreated.');
});

// ---------------------------------------------------------------------------
// Conformance: Event binding helper passes useCapture flag
// ---------------------------------------------------------------------------

Given('the project has an event binding helper function', function () {
  const appPath = path.join(ROOT, 'js', 'app.js');
  assert.ok(fs.existsSync(appPath), 'js/app.js not found');
  const source = fs.readFileSync(appPath, 'utf8');
  this.appSource = source;
  // Check that a helper named 'on' exists and wraps addEventListener
  const hasOnHelper = /function\s+on\s*\(/.test(source);
  const hasAddEventListener = /addEventListener\s*\(/.test(source);
  assert.ok(hasOnHelper && hasAddEventListener,
    'Expected an event binding helper function that wraps addEventListener');
});

When('I check whether the helper passes the useCapture argument to addEventListener', function () {
  const source = this.appSource;
  // Detect whether the 'on' helper passes a capture flag to addEventListener.
  //
  // The BUG: function on(el, evt, fn) { el.addEventListener(evt, fn); }
  // The `on` helper takes only 3 params and addEventListener has only 2 args,
  // so the 4th useCapture argument is silently dropped.
  //
  // The FIX: function on(el, evt, fn, capture) { el.addEventListener(evt, fn, capture); }
  // The helper takes a 4th param and addEventListener receives 3 args.
  //
  // Strategy: extract the function body of the `on` helper and check whether
  // addEventListener is called with exactly 2 arguments (bug) or 3+ (fixed).
  const onMatch = source.match(/function\s+on\s*\(([^)]*)\)\s*\{([^}]*)\}/);
  if (!onMatch) {
    this.onHelperHasCapture = false;
    return;
  }
  const onBody = onMatch[2];
  // Find addEventListener call inside the on body
  const addEventListenerCall = onBody.match(/addEventListener\s*\(([^)]*)\)/);
  if (!addEventListenerCall) {
    this.onHelperHasCapture = false;
    return;
  }
  const args = addEventListenerCall[1].split(',').map(function (a) { return a.trim(); });
  // If addEventListener has 3 args, the third is the capture flag.
  // If only 2 args, the capture flag is not passed.
  this.onHelperHasCapture = args.length >= 3;
});

Then('the helper passes the useCapture flag to the native addEventListener', function () {
  assert.ok(this.onHelperHasCapture,
    'FAIL: The event binding helper function does NOT pass the useCapture/' +
    'options argument to the native addEventListener. ' +
    'The helper wraps addEventListener with only 2 arguments (event, handler), ' +
    'silently dropping any capture flag the caller provides. ' +
    'In a real browser, delegated handlers on non-bubbling events such as ' +
    '"blur" never fire because the capture flag is lost. ' +
    'The harness does not catch this because it dispatches synthetic events ' +
    'with {bubbles: true}.\n' +
    'FIX: Change the helper signature to accept and forward a capture parameter: ' +
    'function on(el, evt, fn, capture) { el.addEventListener(evt, fn, capture); }');
});

